'use client';
import useImageSearch from '@/hooks/useImageSearch';
import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { SearchParams } from 'typesense/lib/Typesense/Documents';
import InfiniteHits from './InfiniteHits';

/*
 * This component make queries to typesense using the props `searchParameters` and render the InfiniteHits
 */
export default function ImageSearch({
  searchParameters,
}: {
  searchParameters: SearchParams;
}) {
  const { hits, fetchNextPage, isLoading, isLastPage, isNoResults } =
    useImageSearch(searchParameters);
  const { ref, inView } = useInView({ threshold: 0.001 });

  // when the div is in view (which mean the user has reached the bottom of the page) -> fetchNextPage
  useEffect(() => {
    if (!inView || isLastPage) return;
    fetchNextPage();
  }, [inView]);

  const render = () => {
    if (isLoading) {
      return <div className='mt-10'>Loading...</div>;
    } else if (isNoResults) {
      return <div>No results were found.</div>;
    } else if (isLastPage) {
      return <div className='mt-20'>That's all!</div>;
    } else
      return <div ref={ref} className='pointer-events-none mt-[-5vmax]'></div>;
  };
  return (
    <section className='flex flex-col items-center'>
      <div className='w-full overflow-hidden rounded-xl'>
        <InfiniteHits hits={hits} />
      </div>
      <div className='font-mono text-sm'>{render()}</div>
    </section>
  );
}

export function capitalizeFirstLetter(string: string) {
  return string.charAt(0).toUpperCase() + string.slice(1);
}

import { typesense } from '@/lib/typesense';
import { _hit } from '@/types/typesenseResponse';
import { useEffect, useRef, useState } from 'react';
import { SearchParams } from 'typesense/lib/Typesense/Documents';

/*
 * Search logic for <ImageSearch/>
 */
export default function useImageSearch(searchParameters: SearchParams) {
  const page = useRef(0);
  const [hits, setHits] = useState<any>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isLastPage, setIsLastPage] = useState(false);
  const [isNoResults, setIsNoResults] = useState(false);

  useEffect(() => {
    fetchNextPage();
  }, []);

  const fetchNextPage = async () => {
    setIsLoading(true);
    page.current++;
    try {
      const res = await typesense
        .collections('DiffusionDB')
        .documents()
        .search({
          ...searchParameters,
          page: page.current,
        });
      const isNoHitsReturned = res.hits?.length ? false : true;
      setIsLastPage(isNoHitsReturned);
      setHits((prev: _hit[]) => {
        setIsNoResults(isNoHitsReturned && prev.length === 0 ? true : false);
        return [...prev, ...(res.hits || [])];
      });
    } catch (error) {
      alert('Sorry, there is an error fetching data!');
    } finally {
      setIsLoading(false);
    }
  };

  return { hits, fetchNextPage, isLoading, isLastPage, isNoResults };
}

'use client';
import { _documentSchema } from '@/types/typesenseResponse';
import Image from 'next/image';
import ImageSearch from './ImageSearch';
import { useEffect, useState } from 'react';
import Modal from './Modal';

/*
 * This component searches for images using typesense document id
 */
export default function ImageSimilaritySearch({
  imageData,
}: {
  imageData: _documentSchema;
}) {
  const [modalData, setModalData] = useState<_documentSchema | null>(null);

  // prevent scrolling when showing the modal
  useEffect(() => {
    document.body.style.overflowY = modalData ? 'hidden' : 'auto';
  }, [modalData]);

  return (
    <>
      <h3 className=' m-auto my-6 w-max font-mono text-xs font-medium text-white-400'>
        Showing images similar to...
      </h3>

      <div
        className='group relative mb-12 h-[calc(18vh+12vmax)] w-full cursor-pointer'
        onClick={() => setModalData(imageData)}
      >
        <Image
          className='h-full w-full object-contain'
          src={`${process.env.NEXT_PUBLIC_IMAGE_BASE_URL ?? 'https://ai-image-search-images.typesense.org'}/${imageData.image_name}`}
          width={0}
          height={0}
          sizes='80vw'
          alt={imageData.prompt}
          unoptimized
        />
        <div className='pointer-events-none absolute inset-0 flex items-end justify-center bg-dark-900 bg-opacity-40 opacity-0 transition group-hover:opacity-100'>
          <div className='mb-4 font-mono text-xs font-medium'>View more</div>
        </div>
      </div>

      <ImageSearch
        searchParameters={{
          q: '*',
          per_page: 25,
          vector_query: `embedding:([], id:${imageData.id}, distance_threshold: 0.8, k: 100)`,
          exclude_fields: ['embedding', 'out_of'], // reduce ~98.5% of bytes transferred over network
        }}
      />
      {modalData && (
        <Modal imageData={modalData} handleClose={() => setModalData(null)} />
      )}
    </>
  );
}

